#import <Foundation/Foundation.h>
#import "../App/AI/Agent/TFAISubtasks.h"
static NSUInteger checks;
static void Check(BOOL ok,NSString *name){if(!ok){NSLog(@"FAIL %@",name);exit(1);}checks++;NSLog(@"PASS %@",name);}
int main(int argc,char **argv){@autoreleasepool{NSString *path=@(argv[1]);TFAISubtasks *tasks=[[TFAISubtasks alloc]initWithPath:path];NSMutableDictionary *finishes=[NSMutableDictionary new];__block NSUInteger cancellations=0;TFAISubtaskExecutor executor=^dispatch_block_t(NSDictionary *task,void(^update)(NSString *,NSString *),void(^done)(NSDictionary *,NSError *)){finishes[task[@"id"]]=[done copy];update(@"Reading",@"Verified partial");return ^{cancellations++;};};NSMutableArray *ids=[NSMutableArray new];for(int i=0;i<3;i++){NSDictionary *row=[tasks start:@"analysis" prompt:@"Inspect source" parent:@"parent" root:@"/test" executor:executor error:nil];Check(row&&[row[@"depth"] intValue]==1,@"bounded depth one starts");[ids addObject:row[@"id"]];}Check(![tasks start:@"analysis" prompt:@"fourth" parent:@"parent" root:@"/test" executor:executor error:nil],@"fourth active task rejected");Check([tasks tasks:@"other"].count==0,@"other parent isolated");Check(![tasks cancel:ids[0] parent:@"other"],@"foreign cancellation denied");Check([tasks cancel:ids[0] parent:@"parent"]&&cancellations==1,@"cancel invokes executor once");Check([tasks cancel:ids[0] parent:@"parent"]&&cancellations==1,@"cancel idempotent");void(^finish)(NSDictionary *,NSError *)=finishes[ids[0]];finish(@{@"summary":@"late"},nil);Check([[[tasks tasks:@"parent"] firstObject][@"state"] isEqual:@"cancelled"],@"late result cannot resurrect cancelled task");NSDictionary *resumed=[tasks resume:ids[0] parent:@"parent" executor:executor error:nil];Check([resumed[@"state"] isEqual:@"running"]&&[resumed[@"partial"] isEqual:@"Verified partial"],@"explicit resume retains partials");finish(@{@"summary":@"stale attempt"},nil);Check([[[tasks tasks:@"parent"] firstObject][@"state"] isEqual:@"running"],@"old attempt cannot complete new task");finish=finishes[ids[0]];finish(@{@"summary":@"Evidence verified"},nil);Check([[[tasks tasks:@"parent"] firstObject][@"result"][@"summary"] isEqual:@"Evidence verified"],@"structured final return retained");TFAISubtasks *reloaded=[[TFAISubtasks alloc]initWithPath:path];Check([reloaded tasks:@"parent"].count==3,@"local tasks persist across restart");Check([[[reloaded tasks:@"parent"] objectAtIndex:1][@"state"] isEqual:@"interrupted"],@"restart does not replay active task");Check([[[reloaded tasks:@"parent"] objectAtIndex:1][@"partial"] isEqual:@"Verified partial"],@"restart preserves partial evidence");Check(![[tasks tasks:@"parent"].firstObject objectForKey:@"root"]&&![[tasks tasks:@"parent"].firstObject objectForKey:@"prompt"],@"model task metadata omits host root and original prompt");Check([tasks canResume:ids[0] parent:@"parent"]&&![tasks canResume:ids[0] parent:@"other"],@"UI continuation stays in original parent");Check(![reloaded canResume:ids[0] parent:@"parent"],@"restart requires new runtime executor before continuation");NSDictionary *continued=[tasks resume:ids[0] parent:@"parent" executor:nil error:nil];Check([continued[@"state"] isEqual:@"running"],@"UI continuation uses retained isolated executor");[tasks cancelParent:@"parent"];Check(cancellations==4,@"parent cancel stops remaining tasks");NSLog(@"TOTAL %lu subtask checks passed",(unsigned long)checks);return 0;}}
